#!/usr/bin/env bash
# Installs Teleport 18.7.0 for teleport.corp.example (generated by the tangra
# deployment wizard). Review it, then run it as root on the new host, next to
# the teleport.yaml downloaded with it.
set -euo pipefail

TELEPORT_VERSION=18.7.0
TELEPORT_DOMAIN=teleport.corp.example
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if [ "$(id -u)" -ne 0 ]; then
  echo "install.sh: run as root" >&2
  exit 1
fi
if [ ! -f "${HERE}/teleport.yaml" ]; then
  echo "install.sh: teleport.yaml is missing next to this script" >&2
  exit 1
fi
for f in /etc/teleport/tls/fullchain.pem /etc/teleport/tls/privkey.pem; do
  if [ ! -f "$f" ]; then
    echo "install.sh: $f is missing: install the certificate for ${TELEPORT_DOMAIN} and *.${TELEPORT_DOMAIN} first" >&2
    exit 1
  fi
done

# 1. Install the pinned version from Teleport's official installer.
curl -fsSL https://cdn.teleport.dev/install.sh | bash -s 18.7.0
if ! teleport version | grep -q "v${TELEPORT_VERSION}"; then
  echo "install.sh: Teleport ${TELEPORT_VERSION} was not installed" >&2
  exit 1
fi

# 2. Install the configuration.
install -m 0600 "${HERE}/teleport.yaml" /etc/teleport.yaml

# 3. Start Teleport now and at boot.
systemctl enable --now teleport
echo "Teleport ${TELEPORT_VERSION} is starting for https://${TELEPORT_DOMAIN}/; continue with setup-commands.txt."
